(()=>{
 'use strict';
 const api='https://wfhurjyouemahvkcfkdz.supabase.co',key='sb_publishable_FIUSELOTsAQaH8dQ6oF-ow_CcISJV5-',sb=supabase.createClient(api,key,globalThis.PortalConnection?.options(api)),C=BundleCore,$=id=>document.getElementById(id);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function plain(value){const area=document.createElement('textarea');area.innerHTML=String(value??'').replace(/</g,'&lt;').replace(/>/g,'&gt;');return area.value;}
 const messages={practice_bundles_not_released:'Practice bundles is being checked before release. Please use your existing course practice for now.',bundle_changed_elsewhere:'A newer save exists in another tab or device.',not_enrolled_in_track:'This course is not currently assigned to your account.',question_content_under_review:'A question in this bundle changed or is under review. Your saved answers remain available. Start a fresh bundle after your instructor reviews it.',finish_an_open_bundle_first:'You have 20 unfinished bundles. Finish one before creating another.',answer_all_questions_or_save:'Answer every question to submit, or save and continue later.',student_account_required:'Practice bundles are available through student accounts.',device_approval_required:'Approve this browser through the portal, then return here.',mfa_required:'Complete sign-in verification in the portal, then return here.',invalid_session:'Sign in to the portal again to continue.'};
 let user,track,rows=[],bundle=null,seq=0,dirty=false,blocked=false,busy=false,timer,offset=0,loadId=0,catalogReady=false,subtopicsSupported=false;
 const notify=(text,error=false)=>{$('message').textContent=text;$('message').classList.toggle('error',error);};
 const status=(text,error=false)=>{$('saveStatus').textContent=text;$('saveStatus').classList.toggle('error',error);};
 function timed(promise){return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('The portal connection timed out. Your saved answers are safe. Please try again.')),20000);Promise.resolve(promise).then(value=>{clearTimeout(timeout);resolve(value);},error=>{clearTimeout(timeout);reject(error);});});}
 async function request(body,query={},endpoint='practice-bundles'){return timed((async()=>{
  const {data:{session}}=await sb.auth.getSession();if(!session)throw Error('Sign in to the portal, then return to Practice bundles.');
  const res=await fetch(api+'/functions/v1/'+endpoint+'?'+new URLSearchParams(query),{method:body?'POST':'GET',headers:{Authorization:'Bearer '+session.access_token,apikey:key,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});
  const data=await res.json();if(!res.ok||data.error){const e=Error(data.error==='not_enough_questions'?`Only ${data.available} questions match. Reduce the count or change your filters.`:messages[data.error]||'The request could not be completed. Please try again.');e.code=data.error;throw e;}return data;
 })());}
 const storageKey=()=>`ghoneem:practice-bundle:${user}:${bundle.id}`;
 function remember(){if(!bundle||bundle.completed_at)return;try{localStorage.setItem(storageKey(),JSON.stringify({revision:bundle.revision,answers:bundle.answers,position:bundle.position}));}catch{status('Local backup unavailable. Keep this page open until the server confirms your save.',true);}}
 function forget(){try{localStorage.removeItem(storageKey());}catch{}}
 const write=C.writer(async submit=>{
  if(!bundle||bundle.completed_at)return true;if(blocked)throw Error('Load the saved version before continuing.');if(!dirty&&!submit)return true;
  const current=bundle,version=seq,answers={...bundle.answers},position=bundle.position;
  status(submit?'Submitting…':'Saving…');
  try{
   const data=await request({action:submit?'submit':'save',track,id:current.id,revision:current.revision,answers,position});
   if(bundle!==current)return false;
   if(data.completed_at){bundle=data;dirty=false;forget();renderQuestion();status('Submitted. Your choices and worked solutions are saved.');return true;}
   bundle.revision=data.revision;dirty=seq!==version;
   if(dirty)remember();else forget();status(dirty?'Saving your latest changes…':'All changes saved');return true;
  }catch(e){remember();if(['bundle_changed_elsewhere','question_content_under_review'].includes(e.code)){blocked=true;showConflict(e.code==='bundle_changed_elsewhere');renderQuestion();}status(e.message+' Your local answers are kept on this device.',true);throw e;}
 });
 function showConflict(show=true){$('conflict').hidden=!show;$('localAnswers').textContent=JSON.stringify(bundle.answers,null,2);}
 function changed(){seq++;dirty=true;remember();status('Changes waiting to save…');clearTimeout(timer);timer=setTimeout(()=>write(false).catch(()=>{}),700);updateControls();}
 function settings(){return {section:$('section').value,topics:[...$('lessonOptions').querySelectorAll('[data-lesson]:checked')].map(x=>x.value),subtopics:[...$('lessonOptions').querySelectorAll('[data-subtopic]:checked')].map(x=>({topic:x.dataset.topic,subtopic:x.value})),difficulty:$('difficulty').value,count:Number($('count').value),exclude_answered:$('exclude').checked};}
 function show(panel){for(const id of ['builder','historyPanel','runner'])$(id).hidden=id!==panel;$('builderTab').setAttribute('aria-pressed',String(panel==='builder'));$('historyTab').setAttribute('aria-pressed',String(panel==='historyPanel'));$('course').disabled=busy||panel==='runner';}
 function renderLessons(preserve=false){
  const old=preserve?settings():{topics:[],subtopics:[]},section=$('section').value,topics=[...new Set([...rows.filter(r=>!section||r.section===section).map(r=>r.topic),...old.topics,...old.subtopics.map(x=>x.topic)])].sort();
  $('lessonOptions').innerHTML=topics.map(t=>{
   const subs=[...new Set([...rows.filter(r=>r.topic===t).map(r=>r.subtopic),...old.subtopics.filter(x=>x.topic===t).map(x=>x.subtopic)])].filter(Boolean).sort();
   return `<div class="bundle-lesson"><label><input type="checkbox" data-lesson value="${esc(t)}" ${old.topics.includes(t)?'checked':''}><span>${esc(t)} <small data-option-count></small></span></label>${subtopicsSupported?`<details><summary>Choose subtopics</summary>${subs.map(sub=>`<label class="bundle-subtopic"><input type="checkbox" data-subtopic data-topic="${esc(t)}" value="${esc(sub)}" ${old.subtopics.some(x=>x.topic===t&&x.subtopic===sub)?'checked':''}><span>${esc(sub)} <small data-option-count></small></span></label>`).join('')}</details>`:''}</div>`;
  }).join('');availability();
 }
 function availability(){
  const s=settings(),n=C.available(rows,s),valid=Number.isInteger(s.count)&&s.count>=1&&s.count<=100;
  $('availability').textContent=!catalogReady?'Refresh the available questions before creating a bundle.':`${n} eligible questions remain for this selection. ${!valid?'Choose a whole number from 1 to 100.':n<s.count?`You requested ${s.count}. Reduce the count or change the filters.`:''}`;
  $('create').disabled=busy||!catalogReady||!valid||n<s.count;
  $('useAvailable').hidden=!catalogReady||n<1||!valid||n>=s.count;
  $('useAvailable').textContent=`Use ${Math.min(n,100)} available questions`;
  for(const label of $('lessonOptions').querySelectorAll('label')){
   const input=label.querySelector('input'),count=label.querySelector('[data-option-count]');
   const one={...s,topics:input.hasAttribute('data-lesson')?[input.value]:[],subtopics:input.hasAttribute('data-subtopic')?[{topic:input.dataset.topic,subtopic:input.value}]:[]};
   count.textContent=`(${C.available(rows,one)} available)`;
  }
 }
 async function loadCatalog(){
  const token=++loadId;catalogReady=false;subtopicsSupported=false;rows=[];renderLessons();notify('Loading topics…');
  try{const data=await request(null,{track,view:'catalog'});if(token!==loadId)return;rows=data.topics;catalogReady=true;subtopicsSupported=!!data.subtopics_supported;
   $('accountNotice').hidden=!data.test_account;$('accountNotice').textContent=data.test_account?'Test account · '+(data.account_name||'Portal test student'):'';
   const sections=track==='sat'&&subtopicsSupported?['Algebra','Advanced Math','Problem-Solving and Data Analysis','Geometry and Trigonometry']:[...new Set(rows.map(r=>r.section))].sort();
   $('section').innerHTML='<option value="">All '+(track==='sat'&&subtopicsSupported?'four domains':'main topics')+'</option>'+sections.map(s=>`<option>${esc(s)}</option>`).join('');
   $('topicNote').textContent=track==='sat'&&subtopicsSupported?'Choose whole lessons or individual subtopics. With none selected, all lessons in the domain are included. Untagged questions appear under General lesson practice. Supplementary or unclassified bank lessons are outside these four domain bundles.':subtopicsSupported?'Choose whole lessons or individual subtopics. With none selected, all lessons in this topic are included. Untagged questions appear under General lesson practice.':'Leave all unchecked to include every lesson in this topic.';
   renderLessons();notify('Choose from the available questions in your course.');show('builder');
  }catch(e){if(token!==loadId)return;notify(e.message,true);$('retry').hidden=false;}
 }
 async function refreshCounts(){
  const token=++loadId;catalogReady=false;availability();
  try{const data=await request(null,{track,view:'catalog'});if(token!==loadId)return;rows=data.topics;catalogReady=true;subtopicsSupported=!!data.subtopics_supported;renderLessons(true);}
  catch(e){if(token===loadId){notify(e.message,true);availability();}}
 }
 async function historyList(){const token=++loadId;show('historyPanel');$('historyList').textContent='Loading saved practice…';try{const result=await request(null,{track,view:'history',offset});if(token!==loadId)return;$('historyList').innerHTML=result.items.length?result.items.map(b=>`<article class="history-row"><div><h3>${esc(b.settings.section||'Mixed topics')}${b.parent_id?' · Retake':''}</h3><p>${b.total} questions · ${esc(b.settings.difficulty)} · ${esc(new Date(b.created_at).toLocaleDateString('en-GB',{timeZone:'Africa/Cairo'}))}</p><p>${b.completed_at?`Submitted · ${b.score}/${b.total} correct`:`In progress · ${b.answered}/${b.total} answered`}</p></div><button data-open="${esc(b.id)}">${b.completed_at?'Review choices & solutions':'Resume bundle'}</button></article>`).join(''):'<div class="bundle-card"><h3>No practice on this page yet.</h3><p>Build a bundle to get started.</p></div>';$('historyPrev').disabled=offset===0;$('historyNext').disabled=result.items.length<20;}catch(e){$('historyList').textContent=e.message;}}
 function adopt(data){bundle=data;seq=0;dirty=false;blocked=!!data.under_review;showConflict(false);if(!bundle.completed_at){let local;try{local=JSON.parse(localStorage.getItem(storageKey()));}catch{}const recovery=C.recovery(bundle,local);if(recovery.kind==='restore'){bundle.answers=recovery.answers;bundle.position=recovery.position;dirty=true;status('Restored your local draft. Saving…');}else if(recovery.kind==='invalid'){forget();notify('An unreadable local draft was found. Your server save has been loaded.',true);}else if(recovery.kind==='conflict'){blocked=true;$('conflict').hidden=false;$('localAnswers').textContent=JSON.stringify(local.answers,null,2);status('A newer version exists. Compare your local answers before loading the saved version.',true);}}show('runner');renderQuestion();history.replaceState(null,'','/practice-bundles.html?'+new URLSearchParams({track,bundle:bundle.id}));if(blocked&&bundle.under_review)status(messages.question_content_under_review,true);else if(!blocked){status(bundle.completed_at?'Submitted. Your choices and solutions are saved.':dirty?'Restored your draft. Saving…':'All changes saved');if(dirty)write(false).catch(()=>{});}}
 async function openBundle(id){if(busy)return;busy=true;++loadId;$('course').disabled=true;notify('Loading your bundle…');try{adopt(await request(null,{track,view:'bundle',id}));notify('');}catch(e){notify(e.message,true);}finally{busy=false;if(bundle)renderQuestion();}}
 async function start(parent=null){if(busy||(!parent&&!catalogReady))return;busy=true;$('course').disabled=true;availability();$('retake').disabled=true;let requestId;
  const s=settings(),signature=JSON.stringify({track,parent,settings:parent?null:s}),pendingKey=`ghoneem:bundle-create:${user}`;
  try{let pending;try{pending=JSON.parse(sessionStorage.getItem(pendingKey));}catch{}requestId=pending?.signature===signature?pending.id:crypto.randomUUID();try{sessionStorage.setItem(pendingKey,JSON.stringify({signature,id:requestId}));}catch{}
   const data=await request({action:parent?'retake':'create',track,request_id:requestId,settings:s,...(parent?{parent_id:parent}:{})});try{sessionStorage.removeItem(pendingKey);}catch{}adopt(data);notify('');
  }catch(e){notify(e.message,true);if(e.code==='not_enough_questions')await refreshCounts();}finally{busy=false;$('course').disabled=!!bundle;availability();if(bundle)renderQuestion();}
 }
 function updateControls(){if(!bundle)return;const done=!!bundle.completed_at,n=C.countAnswers(bundle);$('progress').textContent=done?`${bundle.score}/${bundle.questions.length} correct · submitted`: `${n}/${bundle.questions.length} answered · untimed`;$('submit').hidden=done;$('submit').disabled=busy||blocked||n!==bundle.questions.length;$('retake').hidden=!done;$('retake').disabled=busy;$('pause').textContent=done?'Back to saved practice':'Save & leave';$('previous').disabled=busy||bundle.position===0;$('next').disabled=busy||bundle.position>=bundle.questions.length-1;for(const b of $('questionNav').querySelectorAll('button'))b.classList.toggle('answered',!!String(bundle.answers[b.dataset.indexId]??'').trim());}
 function renderQuestion(){if(!bundle)return;const b=bundle,done=!!b.completed_at;b.position=Math.max(0,Math.min(b.position,b.questions.length-1));const q=b.questions[b.position];$('runTitle').textContent=b.settings.section||'Mixed topics';$('runMeta').textContent=`${$('course').selectedOptions[0]?.textContent||track} · ${b.parent_id?'RETAKE':'PRACTICE'}`;
  $('questionNav').innerHTML=b.questions.map((q,i)=>`<button type="button" data-index="${i}" data-index-id="${esc(q.id)}" aria-current="${i===b.position?'step':'false'}" aria-label="Question ${i+1}">${i+1}</button>`).join('');
  const selected=b.answers[q.id]||'',locked=done||busy||blocked;
  $('question').innerHTML=`<p class="eyebrow">QUESTION ${b.position+1} / ${b.questions.length} · ${esc(q.difficulty)}</p><p class="muted small">${esc(q.topic)}</p><div class="bundle-stem">${esc(q.stem)}</div>${BundleFigures.figure(q.assets)}<fieldset class="bundle-choices"><legend>${done?'Your saved choice':'Your answer'}</legend>${q.type==='mcq'?q.choices.map(c=>`<label><input type="radio" name="answer" value="${esc(c.key)}" ${selected===c.key?'checked':''} ${locked?'disabled':''}><span><b>${esc(c.key)}.</b> ${esc(c.text)}</span></label>`).join(''):`<input class="gridin" aria-label="Your answer" name="answer" inputmode="text" maxlength="250" autocomplete="off" value="${esc(selected)}" ${locked?'disabled':''}><small>Enter a number, decimal or fraction.</small>`}</fieldset>${done?`<div class="bundle-result ${q.is_correct?'':'wrong'}"><strong>${q.is_correct?'Correct':'Review this question'}</strong><p>Your answer: ${esc(selected)}<br>Accepted answer: ${esc(Array.isArray(q.correct)?q.correct.join(' or '):q.correct)}</p><div class="explanation">${esc(plain(q.explanation))}</div></div>`:''}`;
  $('question').querySelectorAll('[name=answer]').forEach(input=>{input.addEventListener(q.type==='mcq'?'change':'input',()=>{bundle.answers[q.id]=input.value;changed();});});PortalMath.render($('question'));updateControls();
 }
 function navigate(n){if(busy)return;bundle.position=n;if(!bundle.completed_at&&!blocked)changed();renderQuestion();}
 async function leave(panel){if(busy)return;clearTimeout(timer);if(bundle&&!bundle.completed_at&&(dirty||blocked)){try{if(blocked){notify('Resolve the saved-version warning before leaving, or use your browser Back button. Your local draft is retained.',true);return;}await write(false);}catch{return;}}bundle=null;history.replaceState(null,'','/practice-bundles.html?'+new URLSearchParams({track}));$('course').disabled=false;if(panel==='historyPanel')await historyList();else await loadCatalog();}
 $('builderForm').onsubmit=e=>{e.preventDefault();start();};$('section').onchange=()=>renderLessons();$('lessonOptions').onchange=e=>{
  const input=e.target,lesson=input.closest('.bundle-lesson');
  if(input.checked&&lesson){if(input.hasAttribute('data-lesson'))lesson.querySelectorAll('[data-subtopic]').forEach(x=>x.checked=false);else if(input.hasAttribute('data-subtopic'))lesson.querySelector('[data-lesson]').checked=false;}
  availability();
 };$('useAvailable').onclick=()=>{const n=C.available(rows,settings());if(catalogReady&&n>0){$('count').value=String(Math.min(n,100));availability();}};$('refreshAvailability').onclick=refreshCounts;for(const id of ['difficulty','count','exclude'])$(id).oninput=availability;
 $('builderTab').onclick=()=>leave('builder');$('historyTab').onclick=()=>leave('historyPanel');$('pause').onclick=()=>leave('historyPanel');$('previous').onclick=()=>navigate(bundle.position-1);$('next').onclick=()=>navigate(bundle.position+1);$('questionNav').onclick=e=>{const b=e.target.closest('[data-index]');if(b)navigate(Number(b.dataset.index));};$('historyList').onclick=e=>{const b=e.target.closest('[data-open]');if(b)openBundle(b.dataset.open);};$('historyPrev').onclick=()=>{offset=Math.max(0,offset-20);historyList();};$('historyNext').onclick=()=>{offset+=20;historyList();};
 $('submit').onclick=async()=>{if(busy||blocked||C.countAnswers(bundle)!==bundle.questions.length)return;if(!confirm('Submit this completed bundle? Your answers will be saved for review. You can retake it as a separate attempt.'))return;busy=true;clearTimeout(timer);renderQuestion();try{await write(true);}catch(e){notify(e.message,true);}finally{busy=false;renderQuestion();}};
 $('retake').onclick=()=>start(bundle.id);
 $('reloadBundle').onclick=async()=>{if(!confirm('Load the server’s saved answers? Copy any local answers you want to keep from the comparison above first.'))return;const id=bundle.id;forget();await openBundle(id);};
 $('course').onchange=()=>{track=$('course').value;offset=0;bundle=null;history.replaceState(null,'','/practice-bundles.html?'+new URLSearchParams({track}));loadCatalog();};$('retry').onclick=()=>{ $('retry').hidden=true;boot();};
 window.addEventListener('beforeunload',e=>{if(dirty){remember();e.preventDefault();e.returnValue='';}});window.addEventListener('online',()=>{if(dirty&&!blocked)write(false).catch(()=>{});});document.addEventListener('visibilitychange',()=>{if(document.hidden&&dirty&&!blocked)write(false).catch(()=>{});});
 async function boot(){if(document.documentElement.dataset.practiceBundlesEnabled==='false'){notify('Practice bundles is being prepared. Continue using your existing course practice for now.');return;}try{const {data:{user:me},error}=await timed(sb.auth.getUser());if(error||!me)throw Error('Sign in to the portal, then return to Practice bundles.');user=me.id;PortalDevices.configure({sb,fnBase:api+'/functions/v1',key,resume:boot});if(!await timed(PortalDevices.ensure()))return;const data=await request(null,{},'me-tracks');if(data.role!=='student')throw Error(messages.student_account_required);const tracks=data.tracks.filter(t=>['sat','est','est2','act2','est_eng','sat_eng'].includes(t.id));if(!tracks.length)throw Error('No active course is assigned to your account.');$('course').innerHTML=tracks.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');const p=new URLSearchParams(location.search);if(tracks.some(t=>t.id===p.get('track')))$('course').value=p.get('track');track=$('course').value;$('workspace').hidden=false;if(p.get('bundle'))await openBundle(p.get('bundle'));else await loadCatalog();}catch(e){notify(e.message,true);$('retry').hidden=false;}}
 window.addEventListener('DOMContentLoaded',boot);
})();
